# Services
class AuthService:
    def __init__(self, db: Session):
        self.db = db

    def get_user(self, username: str):
        return self.db.query(User).filter(User.username == username).first()

    def create_user(self, user: UserCreate):
        db_user = User(**user.dict())
        self.db.add(db_user)
        self.db.commit()
        self.db.refresh(db_user)
        return db_user

class RepositoryService:
    def __init__(self, db: Session):
        self.db = db

    def get_repositories(self, user: User) -> List[RepositoryResponse]:
        if user.platform == PlatformEnum.github:
            return self._get_github_repos(user.access_token)
        elif user.platform == PlatformEnum.gitlab:
            return self._get_gitlab_repos(user.access_token)
        elif user.platform == PlatformEnum.gitea:
            return self._get_gitea_repos(user.access_token)
        else:
            raise ValueError("Unsupported platform")

    def _get_github_repos(self, token: str) -> List[RepositoryResponse]:
        g = Github(token)
        repos = g.get_user().get_repos()
        return [RepositoryResponse(id=repo.id, name=repo.name, owner=repo.owner.login, html_url=repo.html_url) for repo in repos]

    def _get_gitlab_repos(self, token: str) -> List[RepositoryResponse]:
        gl = Gitlab(private_token=token)
        projects = gl.projects.list(all=True)
        return [RepositoryResponse(id=project.id, name=project.name, owner=project.namespace["name"], html_url=project.web_url) for project in projects]

    def _get_gitea_repos(self, token: str) -> List[RepositoryResponse]:
        client = GiteaClient(token=token)
        repos = client.get_user_repos()
        return [RepositoryResponse(id=repo["id"], name=repo["name"], owner=repo["owner"]["name"], html_url=repo["html_url"]) for repo in repos]

# Dependency
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

def get_current_user(token: str = Depends(OAUTH2_SCHEME), db: Session = Depends(get_db)):
    try:
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGORITHM])
        username: str = payload.get("sub")
        if username is None:
            raise HTTPException(status_code=400, detail="Invalid token")
        user = db.query(User).filter(User.username == username).first()
        if user is None:
            raise HTTPException(status_code=400, detail="User not found")
        return user
    except jwt.PyJWTError:
        raise HTTPException(status_code=400, detail="Invalid token")

# API
app = FastAPI()

@app.post("/auth/register")
def register_user(user: UserCreate, db: Session = Depends(get_db)):
    db_user = AuthService(db).get_user(user.username)
    if db_user:
        raise HTTPException(status_code=400, detail="User already exists")
    return AuthService(db).create_user(user)

@app.get("/repos", response_model=RepositoryListResponse)
def get_repositories(user: User = Depends(get_current_user), db: Session = Depends(get_db)):
    repo_service = RepositoryService(db)
    repos = repo_service.get_repositories(user)
    return {"repositories": repos}

